from pathlib import Path
import base64
import gzip

TARGET = Path("nexus-glass-science-cube/runtime-source.js")
ROBOT_SECTION = gzip.decompress(base64.b64decode("")).decode("utf-8")
SYNC_SECTION = gzip.decompress(base64.b64decode("")).decode("utf-8")


def replace_between(source: str, start_marker: str, end_marker: str, replacement: str) -> str:
    start = source.find(start_marker)
    if start < 0:
        raise RuntimeError(f"Missing start marker: {start_marker}")
    end = source.find(end_marker, start)
    if end < 0:
        raise RuntimeError(f"Missing end marker: {end_marker}")
    return source[:start] + replacement.rstrip() + "\n\n" + source[end:]


def main() -> None:
    source = TARGET.read_text(encoding="utf-8")
    source = replace_between(source, "function robotVisual(robot) {", "function spawnRobot(", ROBOT_SECTION)
    source = replace_between(source, "function syncVisuals() {", "function chooseTool(tool) {", SYNC_SECTION)

    rebuild_line = "  recomputeRobot(robot);\n  rebuildRobotVisual(robot);\n"
    if rebuild_line not in source:
        marker = "  recomputeRobot(robot);\n"
        if marker not in source:
            raise RuntimeError("Could not locate detached-part visual rebuild marker")
        source = source.replace(marker, rebuild_line, 1)

    TARGET.write_text(source, encoding="utf-8")
    print(f"Applied robot art pass to {TARGET} ({len(source):,} characters)")


if __name__ == "__main__":
    main()
